import React, { useState, useEffect } from 'react';
import * as LucideIcons from 'lucide-react'; // استيراد عام لتجنب مشاكل الأسماء
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const ProfilePage = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [newSkill, setNewSkill] = useState('');
  
  // البيانات الرسمية لـ Stag.io
  const [profileData, setProfileData] = useState({
    fullName: '',
    github: '',
    portfolio: ''
  });

  const [skills, setSkills] = useState(['React', 'Django']);

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');
      if (!token) { navigate('/'); return; }
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/profile/', {
          headers: { 'Authorization': 'Bearer ' + token }
        });
        if (response.data) {
          setProfileData({
            fullName: response.data.user?.username || '',
            github: response.data.github || '',
            portfolio: response.data.portfolio || ''
          });
        }
      } catch (err) { console.error("Error:", err); }
      finally { setIsLoading(false); }
    };
    fetchProfile();
  }, [navigate]);

  const addSkill = () => {
    if (newSkill.trim() && !skills.includes(newSkill.trim())) {
      setSkills([...skills, newSkill.trim()]);
      setNewSkill('');
    }
  };

  if (isLoading) return <div style={{padding: '50px', textAlign: 'center'}}>Loading...</div>;

  return (
    <div style={{ padding: '30px', backgroundColor: '#f4f7f6', minHeight: '100vh' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '35px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        
        <h2 style={{ color: '#313647', marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <LucideIcons.User color="#4a3f6b" /> Digital CV Settings
        </h2>

        {/* حقل الاسم */}
        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', fontWeight: '600', marginBottom: '8px' }}>Full Name</label>
          <input 
            style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
            value={profileData.fullName}
            onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
          />
        </div>

        {/* المهارات التقنية - متطلب أساسي */}
        <div style={{ marginBottom: '30px', padding: '20px', backgroundColor: '#fcfdfa', borderRadius: '10px', border: '1px solid #eef2e6' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600', marginBottom: '12px' }}>
            <LucideIcons.Code size={18} /> Technical Skills (Tags)
          </label>
          <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
            <input 
              style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={newSkill}
              onChange={(e) => setNewSkill(e.target.value)}
              placeholder="Ex: Java, Flutter"
            />
            <button onClick={addSkill} style={{ padding: '10px 20px', backgroundColor: '#4a3f6b', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
              <LucideIcons.Plus size={18} />
            </button>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
            {skills.map(skill => (
              <span key={skill} style={{ backgroundColor: '#A3B087', color: 'white', padding: '6px 15px', borderRadius: '20px', fontSize: '13px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                {skill}
                <LucideIcons.X size={14} style={{cursor: 'pointer'}} onClick={() => setSkills(skills.filter(s => s !== skill))} />
              </span>
            ))}
          </div>
        </div>
        {/* الروابط */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          <div>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600' }}>
               GitHub
            </label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={profileData.github}
              onChange={(e) => setProfileData({...profileData, github: e.target.value})}
            />
          </div>
          <div>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600' }}>
              <LucideIcons.Link size={18} /> Portfolio
            </label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={profileData.portfolio}
              onChange={(e) => setProfileData({...profileData, portfolio: e.target.value})}
            />
          </div>
        </div>

        <button onClick ={handleSave} style={{ width: '100%', marginTop: '40px', padding: '15px', backgroundColor: '#4a3f6b', color: 'white', border: 'none', borderRadius: '10px', fontWeight: '600', cursor: 'pointer' }}>
          Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
